package ug.audiocity.studio;
import java.util.Random;
/** Original factory synthesis. No proprietary samples or plug-in code. */
public final class Synth {
 public static final String[] NAMES={"Soft keys","FM electric piano","Round bass","Afro pluck","Warm pad","Glass bell","Silk lead","Log drum","Marimba","Brass stab","Nylon pluck","Sub 808"};
 public static final class Config {public int patch;public double attack=.008,decay=.22,sustain=.6,release=.18,tone=.65,detune=5;public Config copy(){Config c=new Config();c.patch=patch;c.attack=attack;c.decay=decay;c.sustain=sustain;c.release=release;c.tone=tone;c.detune=detune;return c;}}
 public static Config factory(int patch){if(patch<0||patch>=NAMES.length)throw new IllegalArgumentException("Unknown synth patch");Config c=new Config();c.patch=patch;switch(patch){case 0:c.decay=.32;c.sustain=.28;break;case 1:c.decay=.6;c.sustain=.25;c.release=.28;c.tone=.75;break;case 2:c.decay=.18;c.sustain=.7;c.release=.1;c.tone=.35;c.detune=0;break;case 3:c.attack=.002;c.decay=.18;c.sustain=.18;c.release=.16;c.tone=.8;break;case 4:c.attack=.35;c.decay=.8;c.sustain=.8;c.release=.85;c.tone=.5;c.detune=14;break;case 5:c.attack=.002;c.decay=.9;c.sustain=.05;c.release=.6;c.tone=.95;c.detune=0;break;case 6:c.attack=.02;c.decay=.18;c.sustain=.7;c.release=.2;c.tone=.65;c.detune=9;break;case 7:c.attack=.001;c.decay=.32;c.sustain=.1;c.release=.18;c.tone=.45;c.detune=0;break;case 8:c.attack=.001;c.decay=.25;c.sustain=.1;c.release=.17;c.tone=.65;c.detune=0;break;case 9:c.attack=.035;c.decay=.2;c.sustain=.55;c.release=.14;c.tone=.8;c.detune=7;break;case 10:c.attack=.002;c.decay=.4;c.sustain=.2;c.release=.24;c.tone=.55;c.detune=2;break;case 11:c.attack=.003;c.decay=.5;c.sustain=.5;c.release=.45;c.tone=.3;c.detune=0;break;}return c;}
 static double clamp(double value,double min,double max){if(!Double.isFinite(value))throw new IllegalArgumentException("Non-finite synth parameter");return Math.max(min,Math.min(max,value));}
 static double envelope(double time,double gate,Config c){if(time>=gate){double at=preEnvelope(gate,c);return at*Math.max(0,1-(time-gate)/c.release);}return preEnvelope(time,c);}
 static double preEnvelope(double t,Config c){if(t<c.attack)return t/c.attack;if(t<c.attack+c.decay)return 1-(1-c.sustain)*(t-c.attack)/c.decay;return c.sustain;}
 static double saw(double phase,double f){double out=0;int harmonics=Math.min(10,(int)(Core.RATE*.46/f));for(int k=1;k<=harmonics;k++)out+=Math.sin(phase*k)/k;return out*.57;}
 public static float[] note(int midi,double gate,Config input){if(midi<21||midi>108||gate<.02||gate>30||!Double.isFinite(gate))throw new IllegalArgumentException("Synth note outside supported range");Config c=input.copy();if(c.patch<0||c.patch>=NAMES.length)throw new IllegalArgumentException("Unknown synth patch");c.attack=clamp(c.attack,.001,.6);c.decay=clamp(c.decay,.02,1.5);c.sustain=clamp(c.sustain,0,1);c.release=clamp(c.release,.02,1.8);c.tone=clamp(c.tone,0,1);c.detune=clamp(c.detune,0,25);int n=(int)Math.ceil((gate+c.release)*Core.RATE);float[] out=new float[n*2];double frequency=440*Math.pow(2,(midi-69)/12.0),phase=0,phase2=0,pitchRatio=Math.pow(2,c.detune/1200),cutoff=Math.min(15000,250+c.tone*c.tone*14500),alpha=1-Math.exp(-2*Math.PI*cutoff/Core.RATE),left=0,right=0;Random random=new Random(91823+midi*17+c.patch*701);int length=Math.max(2,(int)Math.round(Core.RATE/frequency));double[] string=new double[length];for(int i=0;i<length;i++)string[i]=(random.nextDouble()*2-1)*.6;if(c.patch==10)for(int i=0;i<length;i++)string[i]=(string[i]+string[(i+1)%length])*.5;int stringAt=0;
 for(int i=0;i<n;i++){double time=i/(double)Core.RATE,actual=frequency;if(c.patch==7)actual*=1+.6*Math.exp(-time*36);if(c.patch==11)actual*=1+2.2*Math.exp(-time*48);phase+=2*Math.PI*actual/Core.RATE;phase2+=2*Math.PI*frequency*pitchRatio/Core.RATE;double sample=0,spread=0;switch(c.patch){case 0:sample=Math.sin(phase)*.5+Math.sin(phase*2)*.22*Math.exp(-time*3)+Math.sin(phase*3)*.12*Math.exp(-time*5)+Math.sin(phase*4)*.06*Math.exp(-time*7)+Math.sin(phase2)*.3+Math.sin(phase2*2)*.1*Math.exp(-time*3);spread=(Math.sin(phase2)-Math.sin(phase))*.06;break;case 1:sample=Math.sin(phase+1.8*Math.sin(phase*2)*Math.exp(-time*4))*.55+Math.sin(phase2+1.2*Math.sin(phase2*2)*Math.exp(-time*4))*.3+Math.sin(phase*14)*.05*Math.exp(-time*14);spread=(Math.sin(phase2)-Math.sin(phase))*.08;break;case 2:sample=Math.tanh((Math.sin(phase)*.6+Math.sin(phase*2)*.25+Math.sin(phase*3)*.1+Math.sin(phase*.5)*.25)*1.3)*.75;break;case 3:case 10:sample=string[stringAt];double next=(sample+string[(stringAt+1)%length])*.5*(c.patch==3?.995:.998);string[stringAt]=next;stringAt=(stringAt+1)%length;sample=sample*1.6+Math.sin(phase*2)*.08*Math.exp(-time*15);break;case 4:sample=(Math.sin(phase)+Math.sin(phase2)+Math.sin(phase*.5)*.4)*.33;spread=(Math.sin(phase2)-Math.sin(phase))*.13;break;case 5:sample=Math.sin(phase)*.65+Math.sin(phase*2.706)*.23*Math.exp(-time*3)+Math.sin(phase*5.41)*.1*Math.exp(-time*6);break;case 6:sample=(saw(phase,frequency)+saw(phase2,frequency*pitchRatio))*.45;spread=(Math.sin(phase2)-Math.sin(phase))*.07;break;case 7:sample=Math.sin(phase+Math.sin(phase*2)*1.4*Math.exp(-time*9))*.8;break;case 8:sample=Math.sin(phase)*.65+Math.sin(phase*4)*.23*Math.exp(-time*18)+Math.sin(phase*9.9)*.08*Math.exp(-time*30);break;case 9:sample=saw(phase,frequency)*.6+saw(phase2,frequency*pitchRatio)*.3;break;case 11:sample=Math.tanh((Math.sin(phase)+Math.sin(phase*2)*.08)*1.2)*.85;break;}double env=envelope(time,gate,c)*.31;left+=alpha*((sample-spread)*env-left);right+=alpha*((sample+spread)*env-right);double ending=Math.min(1,(n-1-i)/(Core.RATE*.004));out[2*i]=(float)(left*ending);out[2*i+1]=(float)(right*ending);}
 return out;}
 public static float[] chords(int bpm,Config config){if(bpm<40||bpm>240)throw new IllegalArgumentException("Tempo outside range");double bar=4*60.0/bpm;int frames=(int)Math.round(bar*4*Core.RATE);float[] out=new float[frames*2];int[][] notes={{53,57,60},{48,52,55},{46,50,53},{46,50,53}};for(int b=0;b<4;b++)for(int note:notes[b]){double gate=Math.max(.05,bar-Math.min(config.release,bar*.35));float[] voice=note(note,gate,config);int start=(int)Math.round(b*bar*Core.RATE)*2;for(int i=0;i<voice.length&&start+i<out.length;i++)out[start+i]+=voice[i]*.6f;}return out;}
}
